import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());int[] a = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {a[i] = Integer.parseInt(st.nextToken());}if (n == 1) {System.out.println(a[0]);continue;}int[] pref = new int[n];int[] suff = new int[n];pref[0] = a[0];for (int i = 1; i < n; i++) {pref[i] = pref[i - 1] | a[i];}suff[n - 1] = a[n - 1];for (int i = n - 2; i >= 0; i--) {suff[i] = suff[i + 1] | a[i];}int totalOr = pref[n - 1];int maxSave = 0;for (int i = 0; i < n; i++) {int currentOr = 0;if (i == 0) {currentOr = suff[1];} else if (i == n - 1) {currentOr = pref[n - 2];} else {currentOr = pref[i - 1] | suff[i + 1];}if (currentOr == totalOr) {if (a[i] > maxSave) {maxSave = a[i];}}}System.out.println(maxSave);}}}